const raw = $json.output ?? $json.text ?? $json;
let result = raw;

if (typeof raw === 'string') {
  try {
    result = JSON.parse(raw);
  } catch {
    throw new Error('Classifier did not return valid JSON');
  }
}

if (!result || typeof result !== 'object' || Array.isArray(result)) {
  throw new Error('Classifier result must be an object');
}

const confidence = result.confidence;
if (typeof confidence !== 'number'
    || !Number.isFinite(confidence)
    || confidence < 0 || confidence > 1) {
  throw new Error('Classifier confidence must be a number between 0 and 1');
}

const allowed = ['bug', 'task', 'feature', 'unknown'];
const type = allowed.includes(result.type) ? result.type : 'unknown';

return { json: { type, confidence } };
